Approach: parse each line with a regular expression and apply it to a dictionary of variable values.

- Comment lines starting with `//` and blank lines are skipped.
- A line of the form `name <- expr;` evaluates the right-hand side and stores it under `name`.
- To evaluate safely without `eval`, the word `mod` is rewritten as `%`. Then a small recursive-descent evaluator handles integers, variable names, parentheses, and the operators `+ - * / %`. Expressions like `(TMP + 70) mod 100` are covered by this.
- At the end the program prints one line in the format `a ?= <value>; b ?= <value>; TMP ?= <value>;`.

```python
import sys
import re

def tokenize(expr):
    tokens = re.findall(r'\d+|[A-Za-z_]\w*|[()+\-*/%]', expr)
    return tokens

class Parser:
    def __init__(self, tokens, env):
        self.t = tokens
        self.i = 0
        self.env = env

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None

    def take(self):
        tok = self.t[self.i]
        self.i += 1
        return tok

    def expr(self):
        v = self.term()
        while self.peek() in ('+', '-'):
            op = self.take()
            r = self.term()
            v = v + r if op == '+' else v - r
        return v

    def term(self):
        v = self.factor()
        while self.peek() in ('*', '/', '%'):
            op = self.take()
            r = self.factor()
            if op == '*':
                v = v * r
            elif op == '/':
                v = v // r
            else:
                v = v % r
        return v

    def factor(self):
        tok = self.peek()
        if tok == '(':
            self.take()
            v = self.expr()
            if self.peek() == ')':
                self.take()
            return v
        if tok == '-':
            self.take()
            return -self.factor()
        tok = self.take()
        if tok.isdigit():
            return int(tok)
        return self.env.get(tok, 0)

def main():
    data = sys.stdin.read()
    env = {}
    for raw in data.splitlines():
        line = raw.strip()
        if not line or line.startswith('//'):
            continue
        m = re.match(r'^([A-Za-z_]\w*)\s*<-\s*(.*?);?\s*$', line)
        if not m:
            continue
        name, rhs = m.group(1), m.group(2)
        rhs = re.sub(r'\bmod\b', '%', rhs)
        p = Parser(tokenize(rhs), env)
        env[name] = p.expr()
    print("a ?= {}; b ?= {}; TMP ?= {};".format(
        env.get('a', 0), env.get('b', 0), env.get('TMP', 0)))

main()
```
